SELECT age_group AS ageGroup, NVL(SUM(archive_count), 0) AS archiveCount, NVL(SUM(outpatient_count), 0) AS outpatientCount, patient_type AS patientType FROM TR_PAT_PORTRAIT_AGE a LEFT JOIN TR_DEPT_DICT d ON a.dept_code = d.dept_code WHERE a.stat_date BETWEEN #{startDate} AND #{endDate} AND d.outp_or_inp IN (0, 2)
AND a.patient_type = #{patientType}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY a.age_group, a.patient_type ORDER BY a.age_group

SELECT insurance_type AS insuranceType, NVL(SUM(patient_count), 0) AS patientCount, patient_type AS patientType, dept_code AS deptCode, dept_name AS deptName FROM TR_PAT_PORTRAIT_INSUR i LEFT JOIN TR_DEPT_DICT d ON i.dept_code = d.dept_code WHERE i.stat_date BETWEEN #{startDate} AND #{endDate} AND d.outp_or_inp IN (0, 2)
AND i.patient_type = #{patientType}
AND d.dept_code = #{deptCode}
AND d.dept_name LIKE '%' || #{deptName} || '%'
GROUP BY i.insurance_type, i.patient_type, i.dept_code, d.dept_name ORDER BY patientCount DESC

